import{_ as t,o as a,c as s,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-17-save-workspace-template/report3_spec.md","filePath":"feature/agency-workspace/3-4-17-save-workspace-template/report3_spec.md"}'),n={name:"feature/agency-workspace/3-4-17-save-workspace-template/report3_spec.md"};function i(r,e,l,p,c,g){return a(),s("div",null,[...e[0]||(e[0]=[o("<p><strong>3.4.17 Save Workspace Template</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in Agency member saves the configuration of an existing Workspace as a template.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in member of the Agency; no specific role restriction is applied.</li><li><strong>Purpose</strong>: Lets a member store a Workspace configuration as a reusable template so similar Workspaces can be created faster later.</li><li><strong>Interface</strong>: A &quot;Save as Template&quot; modal opened from Workspace settings, plus a &quot;View all templates&quot; link to a separate templates list page. There is no separate detail route/page - the templates list implements detail as an inline expand row.</li><li><strong>Data Processing</strong>: The system stores the template with the configuration snapshot captured from the Workspace, scoped automatically to the caller&#39;s Agency, with creator identity taken from the authenticated session.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Save Workspace Template Screen:</p><ul><li>A &quot;Save as Template&quot; button plus a &quot;View all templates&quot; link, both inside Workspace settings, shown only when the caller can manage.</li><li>The &quot;Save as Template&quot; action opens a modal with a template name input; the configSnapshot is built automatically from the current Workspace&#39;s timezone, defaultPlatforms, and reportFrequency - there is no free-form configSnapshot input and no sourceWorkspaceId picker.</li><li>The templates list page shows each template&#39;s name and creation date; clicking the name toggles an inline expand showing the raw configSnapshot text; a delete button removes it.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name; configSnapshot (a JSON snapshot of the Workspace configuration).</li><li><strong>Input optional</strong>: sourceWorkspaceId.</li><li><strong>System data</strong>: the caller&#39;s authenticated identity; the Agency the caller belongs to; the creation timestamp.</li><li><strong>Output</strong>: the stored template - id, agencyId, name, sourceWorkspaceId, configSnapshot, createdBy, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The Agency and the creator of the template are taken automatically from the caller&#39;s session and never from the request payload; a template is scoped to the caller&#39;s Agency.</li><li><strong>BR-02</strong>: Templates are a standalone resource, not nested inside an Agency or a Workspace; available actions are create, list, delete, and inline-expand-to-view.</li><li><strong>BR-03</strong>: name or configSnapshot empty -&gt; 400 VALIDATION_ERROR.</li><li><strong>BR-04</strong>: Requesting or deleting a template that does not exist -&gt; 404 NOT_FOUND.</li><li><strong>BR-05</strong>: No specific role restriction is currently applied to these actions.</li><li><strong>BR-06</strong>: A template is independent of its source Workspace - it remains available even after that Workspace is deleted.</li><li>getTemplate and deleteTemplate both enforce that the caller owns the template&#39;s Agency; otherwise 403 FORBIDDEN.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>name must not be empty; otherwise 400 VALIDATION_ERROR, <strong>MSG02</strong>.</li><li>configSnapshot must not be empty; otherwise 400 VALIDATION_ERROR, <strong>MSG02</strong>.</li><li>The template must exist for delete/get; otherwise 404 NOT_FOUND, toast <strong>MSG38</strong>.</li><li>Getting or deleting a template belonging to a different Agency -&gt; 403 FORBIDDEN.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Member opens Workspace settings and clicks &quot;Save as Template&quot;, opening a modal.</li><li>Member fills in the template name; the configSnapshot is built automatically from the current Workspace&#39;s timezone/defaultPlatforms/reportFrequency, and sourceWorkspaceId is set to the current workspace&#39;s id.</li><li>System validates that the name and snapshot are not empty.</li><li>System resolves the caller&#39;s owned Agency and attaches agencyId/createdBy automatically.</li><li>System stores the template and returns it; a success toast is shown and the modal closes.</li><li>Member can later open the templates list to expand one inline and view its configSnapshot, or delete it.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: name empty -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>. 3.a2: The user supplies a name and resubmits.</li><li>3.b1: configSnapshot empty -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>. 3.b2: The user captures the configuration and resubmits (cannot happen in the current UI since configSnapshot is always auto-built).</li><li>6.a1: Delete/get requested for a template that does not exist -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 6.a2: The user returns to the template list, which no longer shows that entry.</li><li>6.b1: The source Workspace is deleted after the template was saved -&gt; no error is raised. 6.b2: The template still exists and remains listable.</li><li>6.c1: Delete requested for a template belonging to another Agency -&gt; 403 FORBIDDEN. 6.c2: The user has no access; the template is unaffected.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A template exists within the caller&#39;s Agency with the captured configuration snapshot.</li><li>The template remains available independently of the source Workspace.</li></ul>",14)])])}const h=t(n,[["render",i]]);export{u as __pageData,h as default};
